public class Main {
    public static void main(String[] args) {
        int[][] kursi = {
            {1, 0, 1},
            {0, 1, 1}
        };
        System.out.println("Baris 1 kolom 3: " + kursi[0][2]);
        kursi[1][0] = 1;
        System.out.println("Baris 2 kolom 1: " + kursi[1][0]);
        int terisi = 0;
        for (int b = 0; b < kursi.length; b++) {
            for (int k = 0; k < kursi[b].length; k++) {
                System.out.print(kursi[b][k] + " ");
                terisi += kursi[b][k];
            }
            System.out.println();
        }
        System.out.println("Kursi terisi: " + terisi);
    }
}

